-- End-of-service award recomputed for active staff as if all left on {ASOF}. Columns: eosb_basic, eosb_totwage, tot_yrs, n
-- 0.5 month per year for the first 5 years, then 1 month per year. A = on basic; B = basic + salary items {HT_ITEMS} (housing, transport).
SELECT ROUND(SUM(e)) EOSB_BASIC, ROUND(SUM(e2)) EOSB_TOTWAGE, ROUND(SUM(yrs),1) TOT_YRS, COUNT(*) N FROM (SELECT yrs, b*(CASE WHEN yrs<=5 THEN yrs*0.5 ELSE 2.5+(yrs-5) END) e, w*(CASE WHEN yrs<=5 THEN yrs*0.5 ELSE 2.5+(yrs-5) END) e2 FROM (SELECT MONTHS_BETWEEN(DATE '{ASOF}',(SELECT MIN(x.START_DATE) FROM {P}PS_STAFF_CONTRACT x WHERE x.STAFF_ID=c.STAFF_ID))/12 yrs, (SELECT MAX(s.BASIC_SALARY) FROM {P}PR_STAFF_DEFAULT_SALARY_M s WHERE s.STAFF_ID=c.STAFF_ID AND s.DATE_END IS NULL) b, (SELECT MAX(s.BASIC_SALARY) FROM {P}PR_STAFF_DEFAULT_SALARY_M s WHERE s.STAFF_ID=c.STAFF_ID AND s.DATE_END IS NULL)+NVL((SELECT SUM(d.SALARY_ITEM_AMOUNT) FROM {P}PR_STAFF_DEFAULT_SALARY_D d WHERE d.STAFF_ID=c.STAFF_ID AND d.SALARY_ITEM IN ({HT_ITEMS}) AND d.DATE_START=(SELECT MAX(s2.DATE_START) FROM {P}PR_STAFF_DEFAULT_SALARY_M s2 WHERE s2.STAFF_ID=c.STAFF_ID AND s2.DATE_END IS NULL)),0) w FROM {P}PS_STAFF_CONTRACT c WHERE c.STATUS='A' AND c.CURRENT_CONTRACT='Y'))
